@Test
public void testDataClient() throws TException, InterruptedException, IOException, IllegalPathException {
    assertEquals(1L, (long) SyncClientAdaptor.querySingleSeriesByTimestamp(dataClient, new SingleSeriesQueryRequest()));
    assertEquals(1L, (long) SyncClientAdaptor.querySingleSeries(dataClient, new SingleSeriesQueryRequest(), 0));
    assertEquals(Arrays.asList("1", "2", "3"), SyncClientAdaptor.getNodeList(dataClient, TestUtils.getRaftNode(0, 0), "root", 0));
    assertEquals(new HashSet<>(Arrays.asList("1", "2", "3")), SyncClientAdaptor.getChildNodeInNextLevel(dataClient, TestUtils.getRaftNode(0, 0), "root"));
    assertEquals(new HashSet<>(Arrays.asList("1", "2", "3")), SyncClientAdaptor.getNextChildren(dataClient, TestUtils.getRaftNode(0, 0), "root"));
    MeasurementSchemaRequest request;
    try (ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        DataOutputStream dataOutputStream = new DataOutputStream(byteArrayOutputStream)) {
        new ShowTimeSeriesPlan(new PartialPath("root")).serialize(dataOutputStream);
        request = new MeasurementSchemaRequest(0, TestUtils.getRaftNode(0, 0), TestUtils.getNode(1), ByteBuffer.wrap(byteArrayOutputStream.toByteArray()));
    }
    assertEquals(getAllMeasurementSchemaResult, SyncClientAdaptor.getAllMeasurementSchema(dataClient, request));
    assertEquals(measurementSchemas, SyncClientAdaptor.pullMeasurementSchema(dataClient, new PullSchemaRequest()));
    assertEquals(timeseriesSchemas, SyncClientAdaptor.pullTimeseriesSchema(dataClient, new PullSchemaRequest()));
    assertEquals(aggregateResults, SyncClientAdaptor.getAggrResult(dataClient, new GetAggrResultRequest()));
    assertEquals(paths.subList(0, paths.size() / 2), SyncClientAdaptor.getUnregisteredMeasurements(dataClient, TestUtils.getRaftNode(0, 0), paths));
    List<String> result = new ArrayList<>(SyncClientAdaptor.getAllPaths(dataClient, TestUtils.getRaftNode(0, 0), paths, false).paths);
    assertEquals(paths, result);
    assertEquals(paths.size(), (int) SyncClientAdaptor.getPathCount(dataClient, TestUtils.getRaftNode(0, 0), paths, 0));
    assertEquals(new HashSet<>(paths), SyncClientAdaptor.getAllDevices(dataClient, TestUtils.getRaftNode(0, 0), paths, false));
    assertEquals(1L, (long) SyncClientAdaptor.getGroupByExecutor(dataClient, new GroupByRequest()));
    assertEquals(fillResult, SyncClientAdaptor.previousFill(dataClient, new PreviousFillRequest()));
    assertEquals(readFileResult, SyncClientAdaptor.readFile(dataClient, "a file", 0, 1000));
    assertEquals(aggregateResults, SyncClientAdaptor.getGroupByResult(dataClient, TestUtils.getRaftNode(0, 0), 1, 1, 2));
