@Test
public void test() throws IllegalPathException, InterruptedException {
    LogApplier dummyApplier = log -> {
        if (log instanceof PhysicalPlanLog) {
            PhysicalPlanLog physicalPlanLog = (PhysicalPlanLog) log;
            PhysicalPlan plan = physicalPlanLog.getPlan();
            if (plan instanceof InsertRowPlan) {
                appliedLogs.add(log);
                log.setApplied(true);
            }
        } else {
            // make sure all previous insertions are applied before applying the last log
            if (appliedLogs.size() == 10) {
                appliedLogs.add(log);
                log.setApplied(true);
            }
        }
    };
    AsyncDataLogApplier asyncDataLogApplier = new AsyncDataLogApplier(dummyApplier, "test");
    try {
        for (int i = 0; i < 10; i++) {
            PhysicalPlan plan = new InsertRowPlan(new PartialPath(TestUtils.getTestSg(i)), i, new String[0], new String[0]);
            PhysicalPlanLog log = new PhysicalPlanLog(plan);
            log.setCurrLogIndex(i);
            logsToApply.add(log);
        }
        Log finalLog = new EmptyContentLog();
        finalLog.setCurrLogIndex(10);
        logsToApply.add(finalLog);
        for (Log log : logsToApply) {
            asyncDataLogApplier.apply(log);
        }
        synchronized (finalLog) {
            while (!finalLog.isApplied()) {
                finalLog.wait();
            }
        }
        assertEquals(11, appliedLogs.size());
    } finally {
        asyncDataLogApplier.close();
    }
}

@Test
public void testParallel() {
    LogApplier dummyApplier = log -> {
        if (log instanceof PhysicalPlanLog) {
            PhysicalPlanLog physicalPlanLog = (PhysicalPlanLog) log;
            PhysicalPlan plan = physicalPlanLog.getPlan();
            if (plan instanceof InsertRowPlan) {
                appliedLogs.add(log);
                log.setApplied(true);
            }
        } else {
            appliedLogs.add(log);
            log.setApplied(true);
        }
    };
    AsyncDataLogApplier asyncDataLogApplier = new AsyncDataLogApplier(dummyApplier, "test");
    try {
        for (int i = 0; i < 10; i++) {
            int finalI = i;
            new Thread(() -> {
                List<Log> threadLogsToApply = new ArrayList<>();
                for (int j = 0; j < 10; j++) {
                    PhysicalPlan plan = null;
                    try {
                        plan = new InsertRowPlan(new PartialPath(TestUtils.getTestSg(finalI)), j, new String[0], new String[0]);
                    } catch (IllegalPathException e) {
                        // ignore
                    }
                    PhysicalPlanLog log = new PhysicalPlanLog(plan);
                    log.setCurrLogIndex(finalI * 11 + j);
                    threadLogsToApply.add(log);
                }
                Log finalLog = new EmptyContentLog();
                finalLog.setCurrLogIndex(finalI * 11 + 10);
                threadLogsToApply.add(finalLog);
                for (Log log : threadLogsToApply) {
                    asyncDataLogApplier.apply(log);
                }
            }).start();
        }
        while (appliedLogs.size() < 11 * 10) {
        }
        assertEquals(110, appliedLogs.size());
    } finally {
        asyncDataLogApplier.close();
    }
}

@Test
public void testApplyInsert() throws QueryProcessException, IOException, QueryFilterOptimizationException, StorageEngineException, MetadataException, InterruptedException {
    InsertRowPlan insertPlan = new InsertRowPlan();
    PhysicalPlanLog log = new PhysicalPlanLog();
    log.setPlan(insertPlan);
    // this series is already created
    insertPlan.setDevicePath(new PartialPath(TestUtils.getTestSg(1)));
    insertPlan.setDevicePath(new PartialPath(TestUtils.getTestSg(1)));
    insertPlan.setTime(1);
    insertPlan.setMeasurements(new String[] { TestUtils.getTestMeasurement(0) });
    insertPlan.setDataTypes(new TSDataType[insertPlan.getMeasurements().length]);
    insertPlan.setValues(new Object[] { "1.0" });
    insertPlan.setNeedInferType(true);
    insertPlan.setMeasurementMNodes(new IMeasurementMNode[] { TestUtils.getTestMeasurementMNode(0) });
    applier.apply(log);
    QueryDataSet dataSet = query(Collections.singletonList(TestUtils.getTestSeries(1, 0)), null);
    assertTrue(dataSet.hasNext());
    RowRecord record = dataSet.next();
    assertEquals(1, record.getTimestamp());
    assertEquals(1, record.getFields().size());
    assertEquals(1.0, record.getFields().get(0).getDoubleV(), 0.00001);
    assertFalse(dataSet.hasNext());
    // this series is not created but can be fetched
    insertPlan.setDevicePath(new PartialPath(TestUtils.getTestSg(4)));
    insertPlan.setDevicePath(new PartialPath(TestUtils.getTestSg(4)));
    applier.apply(log);
    dataSet = query(Collections.singletonList(TestUtils.getTestSeries(4, 0)), null);
    assertTrue(dataSet.hasNext());
    record = dataSet.next();
    assertEquals(1, record.getTimestamp());
    assertEquals(1, record.getFields().size());
    assertEquals(1.0, record.getFields().get(0).getDoubleV(), 0.00001);
    assertFalse(dataSet.hasNext());
    // this series does not exists any where
    insertPlan.setDevicePath(new PartialPath(TestUtils.getTestSg(5)));
    insertPlan.setDevicePath(new PartialPath(TestUtils.getTestSg(5)));
    applier.apply(log);
    assertEquals("org.apache.iotdb.db.exception.metadata.PathNotExistException: Path [root.test5.s0] does not exist", log.getException().getMessage());
    // this storage group is not even set
    insertPlan.setDevicePath(new PartialPath(TestUtils.getTestSg(16)));
    insertPlan.setDevicePath(new PartialPath(TestUtils.getTestSg(16)));
    applier.apply(log);
    assertEquals("org.apache.iotdb.db.exception.StorageEngineException: org.apache.iotdb.db.exception.metadata.StorageGroupNotSetException: Storage group is not set for current seriesPath: [root.test16]", log.getException().getMessage());
}

