@Test
public void testSnapshot() throws Exception {
    PartitionTable partitionTable = TestUtils.getPartitionTable(3);
    LogApplier applier = new TestLogApplier();
    FilePartitionedSnapshotLogManager manager = new FilePartitionedSnapshotLogManager(applier, partitionTable, TestUtils.getNode(0), TestUtils.getNode(0), new TestDataGroupMember());
    try {
        List<Log> logs = TestUtils.prepareTestLogs(10);
        manager.append(logs);
        manager.commitTo(10);
        manager.setMaxHaveAppliedCommitIndex(manager.getCommitLogIndex());
        Map<PartialPath, List<Pair<Long, Boolean>>> storageGroupPartitionIds = new HashMap<>();
        // create files for sgs
        for (int i = 1; i < 4; i++) {
            PartialPath sg = new PartialPath(TestUtils.getTestSg(i));
            storageGroupPartitionIds.put(sg, null);
            for (int j = 0; j < 4; j++) {
                // closed files
                prepareData(i, j * 10, 10);
                StorageEngine.getInstance().closeStorageGroupProcessor(sg, true, true);
            }
            // un closed files
            prepareData(i, 40, 10);
        }
        FlushPlan plan = new FlushPlan(null, true, storageGroupPartitionIds);
        PlanExecutor executor = new PlanExecutor();
        executor.processNonQuery(plan);
        List<Integer> requireSlots = new ArrayList<>();
        ((SlotPartitionTable) manager.partitionTable).getAllNodeSlots().values().forEach(requireSlots::addAll);
        manager.takeSnapshotForSpecificSlots(requireSlots, true);
        PartitionedSnapshot snapshot = (PartitionedSnapshot) manager.getSnapshot();
        for (int i = 1; i < 4; i++) {
            FileSnapshot fileSnapshot = (FileSnapshot) snapshot.getSnapshot(SlotPartitionTable.getSlotStrategy().calculateSlotByTime(TestUtils.getTestSg(i), 0, ClusterConstant.SLOT_NUM));
            assertEquals(10, fileSnapshot.getTimeseriesSchemas().size());
            assertEquals(5, fileSnapshot.getDataFiles().size());
        }
    } finally {
        manager.close();
    }
}

@Test
public void testTakeSnapshot() throws Exception {
    try {
        List<Log> testLogs = TestUtils.prepareTestLogs(10);
        logManager.append(testLogs);
        logManager.commitTo(4);
        logManager.setMaxHaveAppliedCommitIndex(logManager.getCommitLogIndex());
        logManager.takeSnapshot();
        MetaSimpleSnapshot snapshot = (MetaSimpleSnapshot) logManager.getSnapshot();
        Map<PartialPath, Long> storageGroupTTLMap = snapshot.getStorageGroupTTLMap();
        PartialPath[] storageGroups = storageGroupTTLMap.keySet().toArray(new PartialPath[0]);
        Arrays.sort(storageGroups);
        assertEquals(10, storageGroups.length);
        for (int i = 0; i < 10; i++) {
            assertEquals(new PartialPath(TestUtils.getTestSg(i)), storageGroups[i]);
        }
        assertEquals(4, snapshot.getLastLogIndex());
        assertEquals(4, snapshot.getLastLogTerm());
    } finally {
        logManager.close();
    }
}

