    CommittedEntryManager committedEntryManager = new CommittedEntryManager(ClusterDescriptor.getInstance().getConfig().getMaxNumOfLogsInMem());
    RaftLogManager instance = new TestRaftLogManager(committedEntryManager, new SyncLogDequeSerializer(testIdentifier), logApplier);
