                        add(new EmptyContentLog(2, 2));
                        add(new EmptyContentLog(3, 3));
                        add(new EmptyContentLog(4, 3));
                    }
                }, 3));
                add(new RaftLogManagerTester(new ArrayList<Log>() {

                    {
                        add(new EmptyContentLog(2, 2));
                        add(new EmptyContentLog(3, 3));
                        add(new EmptyContentLog(4, 3));
                    }
                }, 3));
                add(new RaftLogManagerTester(new ArrayList<Log>() {

                    {
                        add(new EmptyContentLog(3, 3));
                        add(new EmptyContentLog(4, 3));
