@Test
public void testQueryInMemory() throws IOException, StorageEngineException, IllegalPathException, QueryProcessException, StorageGroupNotSetException {
    PlanExecutor planExecutor = new PlanExecutor();
    MeasurementPath[] paths = new MeasurementPath[] { new MeasurementPath(TestUtils.getTestSg(100), TestUtils.getTestMeasurement(0), new MeasurementSchema(TestUtils.getTestMeasurement(0), TSDataType.DOUBLE)), new MeasurementPath(TestUtils.getTestSg(100), TestUtils.getTestMeasurement(1), new MeasurementSchema(TestUtils.getTestMeasurement(1), TSDataType.DOUBLE)), new MeasurementPath(TestUtils.getTestSg(100), TestUtils.getTestMeasurement(2), new MeasurementSchema(TestUtils.getTestMeasurement(2), TSDataType.DOUBLE)) };
    String[] measurements = new String[] { TestUtils.getTestMeasurement(0), TestUtils.getTestMeasurement(1), TestUtils.getTestMeasurement(2) };
    IMeasurementMNode[] schemas = new IMeasurementMNode[] { TestUtils.getTestMeasurementMNode(0), TestUtils.getTestMeasurementMNode(1), TestUtils.getTestMeasurementMNode(2) };
    TSDataType[] dataTypes = new TSDataType[] { TSDataType.DOUBLE, TSDataType.DOUBLE, TSDataType.DOUBLE };
    Object[] values = new Object[] { 1.0, 2.0, 3.0 };
    // set storage group
    SetStorageGroupPlan setStorageGroupPlan = new SetStorageGroupPlan();
    setStorageGroupPlan.setPath(new PartialPath(TestUtils.getTestSg(100)));
    planExecutor.setStorageGroup(setStorageGroupPlan);
    // insert data
    InsertRowPlan insertPlan = new InsertRowPlan();
    insertPlan.setDevicePath(new PartialPath(TestUtils.getTestSg(100)));
    insertPlan.setMeasurements(measurements);
    insertPlan.setMeasurementMNodes(schemas);
    insertPlan.setDataTypes(dataTypes);
    insertPlan.setNeedInferType(true);
    insertPlan.setTime(0);
    insertPlan.setValues(values);
    planExecutor.processNonQuery(insertPlan);
    // query data
    RawDataQueryPlan queryPlan = new RawDataQueryPlan();
    queryPlan.setDeduplicatedPaths(Arrays.asList(paths));
    queryExecutor = new ClusterDataQueryExecutor(queryPlan, testMetaMember);
    RemoteQueryContext context = new RemoteQueryContext(QueryResourceManager.getInstance().assignQueryId(true));
    try {
        QueryDataSet dataSet = queryExecutor.executeWithoutValueFilter(context);
        RowRecord record = dataSet.next();
        List<Field> fields = record.getFields();
        Assert.assertEquals(values.length, fields.size());
        for (int i = 0; i < values.length; i++) {
            Assert.assertEquals(String.valueOf(values[i]), fields.get(i).getStringValue());
        }
        assertFalse(dataSet.hasNext());
    } finally {
        QueryResourceManager.getInstance().endQuery(context.getQueryId());
    }
}

