@Test
public void unloadTsfileTest() throws SQLException {
    try (Connection connection = DriverManager.getConnection("jdbc:iotdb://127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        // move root.vehicle
        List<TsFileResource> resources = new ArrayList<>(StorageEngine.getInstance().getProcessor(new PartialPath("root.vehicle")).getSequenceFileList());
        assertEquals(1, resources.size());
        File tmpDir = new File(resources.get(0).getTsFile().getParentFile().getParentFile(), "tmp" + File.separator + new PartialPath("root.vehicle"));
        if (!tmpDir.exists()) {
            tmpDir.mkdirs();
        }
        for (TsFileResource resource : resources) {
            statement.execute(String.format("unload '%s' '%s'", resource.getTsFilePath(), tmpDir));
        }
        assertEquals(0, StorageEngine.getInstance().getProcessor(new PartialPath("root.vehicle")).getSequenceFileList().size());
        assertNotNull(tmpDir.listFiles());
        assertEquals(1, tmpDir.listFiles().length >> 1);
        // move root.test
        resources = new ArrayList<>(StorageEngine.getInstance().getProcessor(new PartialPath("root.test")).getSequenceFileList());
        assertEquals(2, resources.size());
        tmpDir = new File(resources.get(0).getTsFile().getParentFile().getParentFile(), "tmp" + File.separator + new PartialPath("root.test"));
        if (!tmpDir.exists()) {
            tmpDir.mkdirs();
        }
        for (TsFileResource resource : resources) {
            // test unload using relative path
            statement.execute(String.format("unload '%s' '%s'", "./" + resource.getTsFilePath(), tmpDir));
        }
        assertEquals(0, StorageEngine.getInstance().getProcessor(new PartialPath("root.test")).getSequenceFileList().size());
        assertNotNull(tmpDir.listFiles());
        assertEquals(2, tmpDir.listFiles().length >> 1);
    } catch (StorageEngineException | IllegalPathException e) {
        Assert.fail();
    }
}

