@Test
public void loadTsFileTestWithVerifyMetadata() throws Exception {
    try (Connection connection = DriverManager.getConnection("jdbc:iotdb://127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        List<TsFileResource> resources = new ArrayList<>(StorageEngine.getInstance().getProcessor(new PartialPath("root.vehicle")).getSequenceFileList());
        assertEquals(1, resources.size());
        File vehicleTmpDir = new File(resources.get(0).getTsFile().getParentFile().getParentFile().getParentFile().getParentFile(), "tmp" + File.separator + "root.vehicle");
        if (!vehicleTmpDir.exists()) {
            vehicleTmpDir.mkdirs();
        }
        for (TsFileResource resource : resources) {
            statement.execute(String.format("unload '%s' '%s'", resource.getTsFilePath(), vehicleTmpDir));
        }
        resources = new ArrayList<>(StorageEngine.getInstance().getProcessor(new PartialPath("root.test")).getSequenceFileList());
        assertEquals(2, resources.size());
        File testTmpDir = new File(vehicleTmpDir.getParentFile(), "root.test");
        if (!testTmpDir.exists()) {
            testTmpDir.mkdirs();
        }
        for (TsFileResource resource : resources) {
            statement.execute(String.format("unload '%s' '%s'", resource.getTsFilePath(), testTmpDir));
        }
        for (String sql : deleteSqls) {
            statement.execute(sql);
        }
        List<String> metaDataSqls = new ArrayList<>(Arrays.asList("SET STORAGE GROUP TO root.vehicle", "SET STORAGE GROUP TO root.test", "CREATE TIMESERIES root.vehicle.d0.s0 WITH DATATYPE=INT64, ENCODING=RLE", "CREATE TIMESERIES root.vehicle.d0.s1 WITH DATATYPE=TEXT, ENCODING=PLAIN", "CREATE TIMESERIES root.vehicle.d1.s2 WITH DATATYPE=FLOAT, ENCODING=RLE", "CREATE TIMESERIES root.vehicle.d1.s3 WITH DATATYPE=BOOLEAN, ENCODING=PLAIN", "CREATE ALIGNED TIMESERIES root.test.d0(s0 FLOAT encoding=RLE, s1 TEXT encoding=PLAIN)", "CREATE ALIGNED TIMESERIES root.test.d1.g0(s0 INT32 encoding=RLE)"));
        for (String sql : metaDataSqls) {
            statement.execute(sql);
        }
        // load vehicle
        boolean hasError = false;
        try {
            statement.execute(String.format("load '%s'", vehicleTmpDir));
        } catch (Exception e) {
            hasError = true;
            assertTrue(e.getMessage().contains("is aligned in the loading TsFile but is not aligned in IoTDB."));
        }
        assertTrue(hasError);
        statement.execute(String.format("load '%s' verify=false", vehicleTmpDir));
        assertEquals(1, StorageEngine.getInstance().getProcessor(new PartialPath("root.vehicle")).getSequenceFileList().size());
        // load test
        hasError = false;
        try {
            statement.execute(String.format("load '%s'", testTmpDir));
        } catch (Exception e) {
            hasError = true;
            assertTrue(e.getMessage().contains("because root.test.d0.s0 is INT32 in the loading TsFile but is FLOAT in IoTDB."));
        }
        assertTrue(hasError);
        statement.execute(String.format("load '%s' verify=false", testTmpDir));
        assertEquals(2, StorageEngine.getInstance().getProcessor(new PartialPath("root.test")).getSequenceFileList().size());
    } catch (Exception e) {
        e.printStackTrace();
        Assert.fail();
    }
}

