        List<String> result = new ArrayList<>();
        while (resultSet.next()) {
            result.add(resultSet.getString("Time") + ", " + resultSet.getString("root.sg1.d1.s1"));
            result.add(resultSet.getString("Time") + ", " + resultSet.getString("root.sg1.d1.s2"));
