@Test
public void testCreateTimeseriesWithSpecialCharacter() throws Exception {
    try {
        statement.execute(String.format("create timeseries %s with datatype=INT64, encoding=PLAIN, compression=SNAPPY", "root.sg.d.a\".\"b"));
        fail();
    } catch (SQLException e) {
        Assert.assertEquals("401: Error occurred while parsing SQL to physical plan: line 1:29 mismatched input '\".\"' expecting {DATATYPE, WITH, DATATYPE_VALUE, '('}", e.getMessage());
    }
    try {
        statement.execute(String.format("create timeseries %s with datatype=INT64, encoding=PLAIN, compression=SNAPPY", "root.sg.d.a“（Φ）”b"));
        fail();
    } catch (SQLException e) {
        Assert.assertEquals("401: Error occurred while parsing SQL to physical plan: line 1:29 token recognition error at: '“'", e.getMessage());
    }
    try {
        statement.execute(String.format("create timeseries %s with datatype=INT64, encoding=PLAIN, compression=SNAPPY", "root.sg.d.a>b"));
        fail();
    } catch (SQLException e) {
        Assert.assertEquals("401: Error occurred while parsing SQL to physical plan: line 1:29 mismatched input '>' expecting {DATATYPE, WITH, DATATYPE_VALUE, '('}", e.getMessage());
    }
    String[] timeSeriesArray = { "root.sg.d.`a.b`", "root.sg.d.`a“（Φ）”b`", "root.sg.d.`a>b`" };
    String[] timeSeriesResArray = { "root.sg.d.`a.b`", "root.sg.d.a“（Φ）”b", "root.sg.d.a>b" };
    for (String timeSeries : timeSeriesArray) {
        statement.execute(String.format("create timeseries %s with datatype=INT64, encoding=PLAIN, compression=SNAPPY", timeSeries));
    }
    // ensure that current timeseries in cache is right.
    createTimeSeriesWithSpecialCharacterTool(timeSeriesResArray);
    statement.close();
    connection.close();
    EnvironmentUtils.stopDaemon();
    setUp();
    // ensure timeseries in cache is right after recovered.
    createTimeSeriesWithSpecialCharacterTool(timeSeriesResArray);
}

