    "2022-01-04 01:02:03+01:00", // yyyy/MM/dd HH:mm:ssZZ
    "2022/01/05 01:02:03+01:00", // yyyy.MM.dd HH:mm:ssZZ
    "2022.01.06 01:02:03+01:00", // yyyy-MM-dd HH:mm:ss.SSS
    "2022-01-07 01:02:03.400", // yyyy/MM/dd HH:mm:ss.SSS
    "2022/01/08 01:02:03.400", // yyyy.MM.dd HH:mm:ss.SSS
    "2022.01.09 01:02:03.400", // yyyy-MM-dd HH:mm:ss.SSSZZ
    "2022-01-10 01:02:03.400+01:00", // yyyy/MM/dd HH:mm:ss.SSSZZ
    "2022-01-11 01:02:03.400+01:00", // yyyy.MM.dd HH:mm:ss.SSSZZ
    "2022-01-12 01:02:03.400+01:00", // ISO8601 standard time format
    "2022-01-13T01:02:03.400+01:00" };
    long[] timestamps = { 1640970123000L, 1641056523000L, 1641142923000L, 1641254523000L, 1641340923000L, 1641427323000L, 1641488523400L, 1641574923400L, 1641661323400L, 1641772923400L, 1641859323400L, 1641945723400L, 1642032123400L };
    try (IoTDBConnection connection = (IoTDBConnection) EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
