@Test
public void restartResourceTest() throws SQLException, IllegalPathException, StorageEngineException {
    try (Connection connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        CONFIG.setConcurrentCompactionThread(0);
        double curTimeIndexMemoryThreshold = 1288.5;
        tsFileResourceManager.setTimeIndexMemoryThreshold(curTimeIndexMemoryThreshold);
        for (int i = 0; i < unSeqSQLs.length - 1; i++) {
            statement.execute(unSeqSQLs[i]);
        }
        statement.close();
        List<TsFileResource> seqResources = new ArrayList<>(StorageEngine.getInstance().getProcessor(new PartialPath("root.sg1")).getSequenceFileList());
        assertEquals(5, seqResources.size());
        // Four tsFileResource are degraded in total, 1 are in seqResources and 3 are in
        // unSeqResources. The difference with the multiResourceTest is that last tsFileResource is
        // not close, so degrade method can't be called.
        for (int i = 0; i < seqResources.size(); i++) {
            if (i < 4) {
                assertTrue(seqResources.get(i).isClosed());
            } else {
                assertFalse(seqResources.get(i).isClosed());
            }
            if (i < 1) {
                assertEquals(TimeIndexLevel.FILE_TIME_INDEX, TimeIndexLevel.valueOf(seqResources.get(i).getTimeIndexType()));
            } else {
                assertEquals(TimeIndexLevel.DEVICE_TIME_INDEX, TimeIndexLevel.valueOf(seqResources.get(i).getTimeIndexType()));
            }
        }
        List<TsFileResource> unSeqResources = new ArrayList<>(StorageEngine.getInstance().getProcessor(new PartialPath("root.sg1")).getUnSequenceFileList());
        assertEquals(3, unSeqResources.size());
        for (TsFileResource resource : unSeqResources) {
            assertTrue(resource.isClosed());
            assertEquals(TimeIndexLevel.FILE_TIME_INDEX, TimeIndexLevel.valueOf(resource.getTimeIndexType()));
        }
    }
    try {
        EnvironmentUtils.restartDaemon();
    } catch (Exception e) {
        Assert.fail();
    }
    List<TsFileResource> seqResources = new ArrayList<>(StorageEngine.getInstance().getProcessor(new PartialPath("root.sg1")).getSequenceFileList());
    assertEquals(5, seqResources.size());
    for (int i = 0; i < seqResources.size(); i++) {
        assertTrue(seqResources.get(i).isClosed());
    }
    List<TsFileResource> unSeqResources = new ArrayList<>(StorageEngine.getInstance().getProcessor(new PartialPath("root.sg1")).getUnSequenceFileList());
    assertEquals(3, unSeqResources.size());
    for (TsFileResource resource : unSeqResources) {
        assertEquals(TimeIndexLevel.FILE_TIME_INDEX, TimeIndexLevel.valueOf(resource.getTimeIndexType()));
        assertTrue(resource.isClosed());
    }
    try (Connection connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        boolean hasResultSet = statement.execute("SELECT s1 FROM root.sg1.d1");
        assertTrue(hasResultSet);
        String[] exp = new String[] { "1,1.0", "5,5.0", "9,9.0", "13,13.0" };
        int cnt = 0;
        try (ResultSet resultSet = statement.getResultSet()) {
            while (resultSet.next()) {
                String result = resultSet.getString(TIMESTAMP_STR) + "," + resultSet.getString(2);
                assertEquals(exp[cnt], result);
                cnt++;
            }
        }
    }
}

