        fail();
    } catch (Exception e) {
        Assert.assertEquals("502: Database is read-only, and does not accept non-query operation now", e.getMessage());
    }
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        statement.execute("SET SYSTEM TO WRITABLE");
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    // Sleep 1s to make sure that other nodes have applied 'SET SYSTEM TO WRITABLE'
    Thread.sleep(1000);
    importData(sqls2);
    String[] retArray = new String[] { "1509465600000,true,25.96,v2,true,true,25.96,", "1509465660000,true,24.36,v2,true,true,24.36,", "1509465720000,false,20.09,v1,false,false,20.09,", "1509465780000,false,20.18,v1,false,false,20.18,", "1509465840000,false,21.13,v1,false,false,21.13,", "1509465900000,false,22.72,v1,false,false,22.72,", "1509465960000,false,20.71,v1,false,false,20.71,", "1509466020000,false,21.45,v1,false,false,21.45,", "1509466080000,false,22.58,v1,false,false,22.58,", "1509466140000,false,20.98,v1,false,false,20.98," };
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        boolean hasResultSet = statement.execute("select * from root.** where time>10");
        Assert.assertTrue(hasResultSet);
        try (ResultSet resultSet = statement.getResultSet()) {
            ResultSetMetaData resultSetMetaData = resultSet.getMetaData();
            List<Integer> actualIndexToExpectedIndexList = checkHeader(resultSetMetaData, "Time,root.ln.wf01.wt01.status,root.ln.wf01.wt01.temperature," + "root.ln.wf02.wt02.hardware,root.ln.wf02.wt02.status,root.sgcc.wf03.wt01.status," + "root.sgcc.wf03.wt01.temperature,", new int[] { Types.TIMESTAMP, Types.BOOLEAN, Types.FLOAT, Types.VARCHAR, Types.BOOLEAN, Types.BOOLEAN, Types.FLOAT });
            int cnt = 0;
            while (resultSet.next()) {
                String[] expectedStrings = retArray[cnt].split(",");
                StringBuilder expectedBuilder = new StringBuilder();
                StringBuilder actualBuilder = new StringBuilder();
                for (int i = 1; i <= resultSetMetaData.getColumnCount(); i++) {
                    actualBuilder.append(resultSet.getString(i)).append(",");
