@Test
public void testStringLiteralWithSingleQuote() {
    String[] insertData = { "'string'", "'`string`'", "'``string'", "'\"string\"'", "'\"\"string'", "'\\\"string\\\"'", "'''string'", "'\\'string'", "'\\nstring'", "'\\rstring'", "'@#$%^&*()string'" };
    String[] resultData = { "string", "`string`", "``string", "\"string\"", "\"\"string", "\"string\"", "'string", "'string", "\nstring", "\rstring", "@#$%^&*()string" };
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        statement.execute("CREATE TIMESERIES root.sg1.d1.s1 TEXT");
        for (int i = 0; i < insertData.length; i++) {
            String insertSql = String.format("INSERT INTO root.sg1.d1(time, s1) values (%d, %s)", i, insertData[i]);
            System.out.println("INSERT STATEMENT: " + insertSql);
            statement.execute(insertSql);
        }
        boolean hasResult = statement.execute("SELECT s1 FROM root.sg1.d1");
        Assert.assertTrue(hasResult);
        int cnt = 0;
        ResultSet resultSet = statement.getResultSet();
        while (resultSet.next()) {
            Assert.assertEquals(resultData[cnt], resultSet.getString("root.sg1.d1.s1"));
