@Test
public void testManageTriggersNormally() {
    try (Connection connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        // show
        ResultSet resultSet = statement.executeQuery("show triggers");
        assertFalse(resultSet.next());
        // create trigger
        statement.execute("create trigger trigger_1 before insert on root.vehicle.d1.s1 as 'org.apache.iotdb.db.engine.trigger.example.Accumulator'");
        statement.execute("create trigger trigger_2 after insert on root.vehicle.d1.s2 as 'org.apache.iotdb.db.engine.trigger.example.Counter'");
        assertFalse(((Accumulator) TriggerRegistrationService.getInstance().getTriggerInstance("trigger_1")).isStopped());
        assertFalse(((Counter) TriggerRegistrationService.getInstance().getTriggerInstance("trigger_2")).isStopped());
        // show
        resultSet = statement.executeQuery("show triggers");
        assertTrue(resultSet.next());
        assertTrue(resultSet.next());
        assertFalse(resultSet.next());
        // stop trigger
        statement.execute("stop trigger trigger_1");
        assertTrue(((Accumulator) TriggerRegistrationService.getInstance().getTriggerInstance("trigger_1")).isStopped());
        // show
        resultSet = statement.executeQuery("show triggers");
        assertTrue(resultSet.next());
        assertTrue(resultSet.next());
        assertFalse(resultSet.next());
        // start trigger
        statement.execute("start trigger trigger_1");
        assertFalse(((Accumulator) TriggerRegistrationService.getInstance().getTriggerInstance("trigger_1")).isStopped());
        // drop trigger
        statement.execute("drop trigger trigger_1");
        statement.execute("drop trigger trigger_2");
        // show
        resultSet = statement.executeQuery("show triggers");
        assertFalse(resultSet.next());
    } catch (SQLException | TriggerManagementException throwable) {
        fail(throwable.getMessage());
    }
}

