@Test
@SuppressWarnings("squid:S5961")
public void testRecovery() throws Exception {
    try (Connection connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        statement.execute("create trigger trigger_1 before insert on root.vehicle.d1.s1 as 'org.apache.iotdb.db.engine.trigger.example.Accumulator' with ('k1'='v1', 'k2'='v2')");
        statement.execute("stop trigger trigger_1");
        statement.execute("start trigger trigger_1");
        statement.execute("drop trigger trigger_1");
        statement.execute("create trigger trigger_1 before insert on root.vehicle.d1.s2 as 'org.apache.iotdb.db.engine.trigger.example.Counter' with ('k3'='v3')");
        statement.execute("stop trigger trigger_1");
        statement.execute("start trigger trigger_1");
        statement.execute("drop trigger trigger_1");
        statement.execute("create trigger trigger_1 after insert on root.vehicle.d1.s3 as 'org.apache.iotdb.db.engine.trigger.example.Counter'");
        statement.execute("create trigger trigger_2 before insert on root.vehicle.d1.s4 as 'org.apache.iotdb.db.engine.trigger.example.Accumulator' with ('k4'='v4')");
        statement.execute("stop trigger trigger_1");
    } catch (Exception e) {
        fail(e.getMessage());
    }
    EnvironmentUtils.restartDaemon();
    try (Connection connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        TriggerRegistrationInformation trigger1Info = TriggerRegistrationService.getInstance().getRegistrationInformation("trigger_1");
        assertEquals("trigger_1", trigger1Info.getTriggerName());
        assertEquals("root.vehicle.d1.s3", trigger1Info.getFullPath().getFullPath());
        assertEquals(TriggerEvent.AFTER_INSERT, trigger1Info.getEvent());
        assertEquals("org.apache.iotdb.db.engine.trigger.example.Counter", trigger1Info.getClassName());
        assertEquals("{}", trigger1Info.getAttributes().toString());
        assertTrue(trigger1Info.isStopped());
        TriggerRegistrationInformation trigger2Info = TriggerRegistrationService.getInstance().getRegistrationInformation("trigger_2");
        assertEquals("trigger_2", trigger2Info.getTriggerName());
        assertEquals("root.vehicle.d1.s4", trigger2Info.getFullPath().getFullPath());
        assertEquals(TriggerEvent.BEFORE_INSERT, trigger2Info.getEvent());
        assertEquals("org.apache.iotdb.db.engine.trigger.example.Accumulator", trigger2Info.getClassName());
        assertEquals("{k4=v4}", trigger2Info.getAttributes().toString());
        assertFalse(trigger2Info.isStopped());
        statement.execute("drop trigger trigger_2");
        statement.execute("drop trigger trigger_1");
        statement.execute("create trigger trigger_2 after insert on root.vehicle.d1.s3 as 'org.apache.iotdb.db.engine.trigger.example.Counter'");
        statement.execute("create trigger trigger_1 before insert on root.vehicle.d1.s4 as 'org.apache.iotdb.db.engine.trigger.example.Accumulator' with ('k5'='v5')");
        statement.execute("stop trigger trigger_2");
        statement.execute("create trigger trigger_3 before insert on root.vehicle.d1.s2 as 'org.apache.iotdb.db.engine.trigger.example.Accumulator'");
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    EnvironmentUtils.restartDaemon();
    TriggerRegistrationInformation trigger1Info = TriggerRegistrationService.getInstance().getRegistrationInformation("trigger_1");
    assertEquals("trigger_1", trigger1Info.getTriggerName());
    assertEquals("root.vehicle.d1.s4", trigger1Info.getFullPath().getFullPath());
    assertEquals(TriggerEvent.BEFORE_INSERT, trigger1Info.getEvent());
    assertEquals("org.apache.iotdb.db.engine.trigger.example.Accumulator", trigger1Info.getClassName());
    assertEquals("{k5=v5}", trigger1Info.getAttributes().toString());
    assertFalse(trigger1Info.isStopped());
    TriggerRegistrationInformation trigger2Info = TriggerRegistrationService.getInstance().getRegistrationInformation("trigger_2");
    assertEquals("trigger_2", trigger2Info.getTriggerName());
    assertEquals("root.vehicle.d1.s3", trigger2Info.getFullPath().getFullPath());
    assertEquals(TriggerEvent.AFTER_INSERT, trigger2Info.getEvent());
    assertEquals("org.apache.iotdb.db.engine.trigger.example.Counter", trigger2Info.getClassName());
    assertEquals("{}", trigger2Info.getAttributes().toString());
    assertTrue(trigger2Info.isStopped());
    TriggerRegistrationInformation trigger3Info = TriggerRegistrationService.getInstance().getRegistrationInformation("trigger_3");
    assertEquals("trigger_3", trigger3Info.getTriggerName());
    assertEquals("root.vehicle.d1.s2", trigger3Info.getFullPath().getFullPath());
    assertEquals(TriggerEvent.BEFORE_INSERT, trigger3Info.getEvent());
    assertEquals("org.apache.iotdb.db.engine.trigger.example.Accumulator", trigger3Info.getClassName());
    assertEquals("{}", trigger3Info.getAttributes().toString());
    assertFalse(trigger3Info.isStopped());
}

@Test
@Category({ ClusterTest.class })
public void testTTL() throws SQLException, InterruptedException {
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        try {
            statement.execute("SET TTL TO root.TTL_SG1 1000");
        } catch (SQLException e) {
            assertEquals(TSStatusCode.TIMESERIES_NOT_EXIST.getStatusCode(), e.getErrorCode());
        }
        try {
            statement.execute("UNSET TTL TO root.TTL_SG1");
        } catch (SQLException e) {
            assertEquals(TSStatusCode.TIMESERIES_NOT_EXIST.getStatusCode(), e.getErrorCode());
        }
        statement.execute("SET STORAGE GROUP TO root.TTL_SG1");
        statement.execute("CREATE TIMESERIES root.TTL_SG1.s1 WITH DATATYPE=INT64,ENCODING=PLAIN");
        try {
            statement.execute("SET TTL TO root.TTL_SG1.s1 1000");
        } catch (SQLException e) {
            assertEquals(TSStatusCode.STORAGE_GROUP_NOT_EXIST.getStatusCode(), e.getErrorCode());
        }
        long now = System.currentTimeMillis();
        for (int i = 0; i < 100; i++) {
            statement.execute(String.format("INSERT INTO root.TTL_SG1(timestamp, s1) VALUES (%d, %d)", now - 100 + i, i));
        }
        for (int i = 0; i < 100; i++) {
            statement.execute(String.format("INSERT INTO root.TTL_SG1(timestamp, s1) VALUES (%d, %d)", now - 100000 + i, i));
        }
        try (ResultSet resultSet = statement.executeQuery("SELECT s1 FROM root.TTL_SG1")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertEquals(200, cnt);
        }
        statement.execute("SET TTL TO root.TTL_SG1 10000");
        try (ResultSet resultSet = statement.executeQuery("SELECT s1 FROM root.TTL_SG1")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertEquals(100, cnt);
        }
        for (int i = 0; i < 100; i++) {
            boolean caught = false;
            try {
                statement.execute(String.format("INSERT INTO root.TTL_SG1(timestamp, s1) VALUES (%d, %d)", now - 500000 + i, i));
            } catch (SQLException e) {
                if (TSStatusCode.OUT_OF_TTL_ERROR.getStatusCode() == e.getErrorCode()) {
                    caught = true;
                }
            }
            assertTrue(caught);
        }
        try (ResultSet resultSet = statement.executeQuery("SELECT s1 FROM root.TTL_SG1")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertEquals(100, cnt);
        }
        statement.execute("UNSET TTL TO root.TTL_SG1");
        // make sure other nodes have applied UNSET TTL
        Thread.sleep(1000);
        for (int i = 0; i < 100; i++) {
            statement.execute(String.format("INSERT INTO root.TTL_SG1(timestamp, s1) VALUES (%d, %d)", now - 30000 + i, i));
        }
        try (ResultSet resultSet = statement.executeQuery("SELECT s1 FROM root.TTL_SG1")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertTrue(cnt >= 200);
        }
    }
}

