@Test
public void testInsertPartialAlignedTablet() throws IoTDBConnectionException, StatementExecutionException {
    List<String> multiMeasurementComponents = new ArrayList<>();
    for (int i = 1; i <= 3; i++) {
        multiMeasurementComponents.add("s" + i);
    }
    List<TSDataType> dataTypes = new ArrayList<>();
    dataTypes.add(TSDataType.INT64);
    dataTypes.add(TSDataType.DOUBLE);
    dataTypes.add(TSDataType.INT64);
    List<TSEncoding> encodings = new ArrayList<>();
    List<CompressionType> compressors = new ArrayList<>();
    for (int i = 1; i <= 3; i++) {
        encodings.add(TSEncoding.PLAIN);
        compressors.add(CompressionType.SNAPPY);
    }
    session.createAlignedTimeseries("root.sg.d", multiMeasurementComponents, dataTypes, encodings, compressors, null, null, null);
    List<MeasurementSchema> schemaList = new ArrayList<>();
    schemaList.add(new MeasurementSchema("s1", TSDataType.INT64));
    schemaList.add(new MeasurementSchema("s2", TSDataType.DOUBLE));
    schemaList.add(new MeasurementSchema("s3", TSDataType.TEXT));
    Tablet tablet = new Tablet("root.sg.d", schemaList, 10);
    long timestamp = System.currentTimeMillis();
    for (long row = 0; row < 15; row++) {
        int rowIndex = tablet.rowSize++;
        tablet.addTimestamp(rowIndex, timestamp);
        tablet.addValue("s1", rowIndex, 1L);
        tablet.addValue("s2", rowIndex, 1D);
        tablet.addValue("s3", rowIndex, new Binary("1"));
        if (tablet.rowSize == tablet.getMaxRowNumber()) {
            try {
                session.insertAlignedTablet(tablet, true);
            } catch (StatementExecutionException e) {
                Assert.assertEquals("313: failed to insert measurements [s3] caused by DataType mismatch, Insert timeseries root.sg.d.s3 type TEXT, metadata tree type INT64", e.getMessage());
            }
            tablet.reset();
        }
        timestamp++;
    }
    if (tablet.rowSize != 0) {
        try {
            session.insertAlignedTablet(tablet);
        } catch (StatementExecutionException e) {
            Assert.assertEquals("313: failed to insert measurements [s3] caused by DataType mismatch, Insert timeseries root.sg.d.s3 type TEXT, metadata tree type INT64", e.getMessage());
        }
        tablet.reset();
    }
    SessionDataSet dataSet = session.executeQueryStatement("select s1, s2, s3 from root.sg.d");
    while (dataSet.hasNext()) {
        RowRecord rowRecord = dataSet.next();
        Assert.assertEquals(1, rowRecord.getFields().get(0).getLongV());
        Assert.assertEquals(1.0, rowRecord.getFields().get(1).getDoubleV(), 0.01);
        Assert.assertEquals(null, rowRecord.getFields().get(2).getObjectValue(TSDataType.TEXT));
    }
}

@Test
public void insert() {
    SessionPool pool = new SessionPool("127.0.0.1", 6667, "root", "root", 3);
    ExecutorService service = Executors.newFixedThreadPool(10);
    for (int i = 0; i < 10; i++) {
        final int no = i;
        service.submit(() -> {
            try {
                pool.insertRecord("root.sg1.d1", 1, Collections.singletonList("s" + no), Collections.singletonList(TSDataType.INT64), Collections.singletonList(3L));
            } catch (IoTDBConnectionException | StatementExecutionException e) {
                fail(e.getMessage());
            }
        });
    }
    service.shutdown();
    try {
        assertTrue(service.awaitTermination(10, TimeUnit.SECONDS));
        assertTrue(pool.currentAvailableSize() <= 3);
        assertEquals(0, pool.currentOccupiedSize());
    } catch (InterruptedException e) {
        logger.error("insert failed", e);
        fail(e.getMessage());
    } finally {
        pool.close();
    }
}

