@Test
public void testGetColumnCount() {
    metadata = new IoTDBResultMetadata(false, null, "QUERY", null, null, false);
    boolean flag = false;
    try {
        metadata.getColumnCount();
    } catch (Exception e) {
        flag = true;
    }
    assertFalse(flag);
    flag = false;
    try {
        metadata = new IoTDBResultMetadata(false, null, "QUERY", Collections.emptyList(), null, false);
        metadata.getColumnCount();
    } catch (Exception e) {
        flag = true;
    }
    assertFalse(flag);
    List<String> columnInfoList = new ArrayList<>();
    columnInfoList.add("root.a.b.c");
    metadata = new IoTDBResultMetadata(false, null, "QUERY", columnInfoList, null, false);
    assertEquals(1, metadata.getColumnCount());
}

@Test
public void testGetColumnName() throws SQLException {
    metadata = new IoTDBResultMetadata(false, null, "QUERY", null, null, false);
    boolean flag = false;
    try {
        metadata.getColumnName(1);
    } catch (Exception e) {
        flag = true;
    }
    assertTrue(flag);
    List<String> columnInfoList = new ArrayList<>();
    metadata = new IoTDBResultMetadata(false, null, "QUERY", columnInfoList, null, false);
    flag = false;
    try {
        metadata.getColumnName(1);
    } catch (Exception e) {
        flag = true;
    }
    assertTrue(flag);
    String[] colums = { "root.a.b.c1", "root.a.b.c2", "root.a.b.c3" };
    metadata = new IoTDBResultMetadata(false, null, "QUERY", Arrays.asList(colums), null, false);
    flag = false;
    try {
        metadata.getColumnName(colums.length + 1);
    } catch (Exception e) {
        flag = true;
    }
    assertTrue(flag);
    flag = false;
    try {
        metadata.getColumnName(0);
    } catch (Exception e) {
        flag = true;
    }
    assertTrue(flag);
    for (int i = 1; i <= colums.length; i++) {
        assertEquals(metadata.getColumnLabel(i), colums[i - 1]);
    }
}

@Test
public void testGetColumnType() throws SQLException {
    metadata = new IoTDBResultMetadata(false, null, "QUERY", null, null, false);
    boolean flag = false;
    try {
        metadata.getColumnType(1);
    } catch (Exception e) {
        flag = true;
    }
    assertTrue(flag);
    List<String> columnInfoList = new ArrayList<>();
    metadata = new IoTDBResultMetadata(false, null, "QUERY", columnInfoList, null, false);
    flag = false;
    try {
        metadata.getColumnType(1);
    } catch (Exception e) {
        flag = true;
    }
    assertTrue(flag);
    String[] columns = { "timestamp", "root.a.b.boolean", "root.a.b.int32", "root.a.b.int64", "root.a.b.float", "root.a.b.double", "root.a.b.text" };
    String[] typesString = { "TIMESTAMP", "BOOLEAN", "INT32", "INT64", "FLOAT", "DOUBLE", "TEXT" };
    int[] types = { Types.BOOLEAN, Types.INTEGER, Types.BIGINT, Types.FLOAT, Types.DOUBLE, Types.VARCHAR };
    metadata = new IoTDBResultMetadata(false, null, "QUERY", Arrays.asList(columns), Arrays.asList(typesString), false);
    flag = false;
    try {
        metadata.getColumnType(columns.length + 1);
    } catch (Exception e) {
        flag = true;
    }
    assertTrue(flag);
    flag = false;
    try {
        metadata.getColumnType(0);
    } catch (Exception e) {
        flag = true;
    }
    assertTrue(flag);
    assertEquals(Types.TIMESTAMP, metadata.getColumnType(1));
    for (int i = 1; i <= types.length; i++) {
        assertEquals(metadata.getColumnType(i + 1), types[i - 1]);
    }
}

