public void testRepeatedSubmitWhenExecuting() throws Exception {
    logger.warn("testRepeatedSubmitWhenExecuting");
    TsFileManager tsFileManager = new TsFileManager("root.compactionTest", "0", tempSGDir.getAbsolutePath());
    tsFileManager.addAll(seqResources, true);
    InnerSpaceCompactionTask task1 = new InnerSpaceCompactionTask(0, tsFileManager, seqResources, true, new ReadChunkCompactionPerformer(seqResources), new AtomicInteger(0));
