            logger.warn("{}", CompactionTaskManager.getInstance().getRunningCompactionTaskList());
        }
        if (waitingTime > MAX_WAITING_TIME) {
            Assert.fail();
        }
    }
    for (TsFileResource resource : seqResources) {
        Assert.assertFalse(resource.isCompactionCandidate());
    }
}

