@Test
public void testSelectContinuousUnseqFile() throws IOException, WriteProcessException, MergeException {
    List<TsFileResource> seqList = new ArrayList<>();
    List<TsFileResource> unseqList = new ArrayList<>();
    try {
        // seq files [0,0] [1,1] [2,2] ... [99,99]
        int seqFileNum = 99;
        for (int i = 0; i < seqFileNum; i++) {
            File file = new File(TestConstant.BASE_OUTPUT_PATH.concat(10 + "seq" + IoTDBConstant.FILE_NAME_SEPARATOR + i + IoTDBConstant.FILE_NAME_SEPARATOR + 10 + IoTDBConstant.FILE_NAME_SEPARATOR + 0 + ".tsfile"));
            TsFileResource fileResource = new TsFileResource(file);
            fileResource.setStatus(TsFileResourceStatus.CLOSED);
            prepareFile(fileResource, i, 1, 0);
            seqList.add(fileResource);
        }
        int unseqFileNum = 3;
        // 3 unseq files [0,0] [0,99] [99,99]
        for (int i = 0; i < unseqFileNum; i++) {
            File file = new File(TestConstant.BASE_OUTPUT_PATH.concat(10 + "unseq" + IoTDBConstant.FILE_NAME_SEPARATOR + i + IoTDBConstant.FILE_NAME_SEPARATOR + 10 + IoTDBConstant.FILE_NAME_SEPARATOR + 0 + ".tsfile"));
            TsFileResource fileResource = new TsFileResource(file);
            fileResource.setStatus(TsFileResourceStatus.CLOSED);
            unseqList.add(fileResource);
        }
        prepareFile(unseqList.get(0), 0, 1, 10);
        prepareFile(unseqList.get(1), 0, 100, 20);
        prepareFile(unseqList.get(2), 99, 1, 30);
        RewriteCrossSpaceCompactionResource resource = new RewriteCrossSpaceCompactionResource(seqList, unseqList);
        // the budget is enough to select unseq0 and unseq2, but not unseq1
        // the first selection should only contain seq0 and unseq0
        ICrossSpaceMergeFileSelector mergeFileSelector = new RewriteCompactionFileSelector(resource, 29000);
        List[] result = mergeFileSelector.select();
        assertEquals(1, result[0].size());
        assertEquals(1, result[1].size());
        assertEquals(seqList.get(0), result[0].get(0));
        assertEquals(unseqList.get(0), result[1].get(0));
        resource.clear();
        resource = new RewriteCrossSpaceCompactionResource(seqList.subList(1, seqList.size()), unseqList.subList(1, unseqList.size()));
        // Although memory is out of memoryBudget, at least one unseq file should be selected
        mergeFileSelector = new RewriteCompactionFileSelector(resource, 29000);
        result = mergeFileSelector.select();
        assertEquals(2, result.length);
        resource.clear();
    } finally {
        removeFiles(seqList, unseqList);
    }
}

