/**
 * Test when all source files exist, and target file is not complete. System should delete target
 * file and its resource at this time.
 *
 * @throws Exception
 */
@Test
public void testWhenAllSourceExistsAndTargetNotComplete() throws Exception {
    tsFileManager.addAll(seqResources, true);
    tsFileManager.addAll(unseqResources, false);
    TsFileResource targetResource = TsFileNameGenerator.getInnerCompactionTargetFileResource(seqResources, true);
    File logFile = new File(targetResource.getTsFile().getPath() + CompactionLogger.INNER_COMPACTION_LOG_NAME_SUFFIX);
    CompactionLogger compactionLogger = new CompactionLogger(logFile);
    compactionLogger.logFiles(seqResources, CompactionLogger.STR_SOURCE_FILES);
    compactionLogger.logFiles(Collections.singletonList(targetResource), CompactionLogger.STR_TARGET_FILES);
    new ReadChunkCompactionPerformer(seqResources, targetResource).perform();
    CompactionUtils.moveTargetFile(Collections.singletonList(targetResource), true, COMPACTION_TEST_SG);
    try (FileOutputStream os = new FileOutputStream(targetResource.getTsFile(), true);
        FileChannel channel = os.getChannel()) {
        channel.truncate(targetResource.getTsFileSize() - 10);
    }
    compactionLogger.close();
    CompactionExceptionHandler.handleException(COMPACTION_TEST_SG, logFile, Collections.singletonList(targetResource), seqResources, Collections.emptyList(), tsFileManager, 0, true, true);
    Assert.assertFalse(targetResource.getTsFile().exists());
    Assert.assertFalse(targetResource.resourceFileExists());
    for (TsFileResource resource : seqResources) {
        Assert.assertTrue(resource.resourceFileExists());
        Assert.assertTrue(resource.getTsFile().exists());
    }
    Assert.assertTrue(tsFileManager.isAllowCompaction());
}

