/**
 * Generate files that chunk are smaller than target chunk point num but greater than lower bound,
 * and the chunk will be merged.
 *
 * @throws Exception
 */
@Test
public void testMergeChunk() throws Exception {
    long testTargetChunkPointNum = 1000L;
    long originTargetChunkSize = IoTDBDescriptor.getInstance().getConfig().getTargetChunkSize();
    long originTargetChunkPointNum = IoTDBDescriptor.getInstance().getConfig().getTargetChunkPointNum();
    IoTDBDescriptor.getInstance().getConfig().setTargetChunkSize(10240);
    IoTDBDescriptor.getInstance().getConfig().setTargetChunkPointNum(testTargetChunkPointNum);
    long originChunkSizeLowerBound = IoTDBDescriptor.getInstance().getConfig().getChunkSizeLowerBoundInCompaction();
    IoTDBDescriptor.getInstance().getConfig().setChunkSizeLowerBoundInCompaction(1);
    long originChunkPointNumLowerBound = IoTDBDescriptor.getInstance().getConfig().getChunkPointNumLowerBoundInCompaction();
    IoTDBDescriptor.getInstance().getConfig().setChunkPointNumLowerBoundInCompaction(1);
    try {
        List<TsFileResource> sourceFiles = new ArrayList();
        Set<String> fullPathSetWithDeleted = new HashSet<>(fullPathSet);
        // we add a deleted timeseries to simulate timeseries is deleted before compaction.
        String deletedPath = "root.compactionTest.device999.s999";
        fullPathSetWithDeleted.add(deletedPath);
        int fileNum = 6;
        long pointStep = 300L;
        for (int i = 0; i < fileNum; ++i) {
            List<List<Long>> chunkPagePointsNum = new ArrayList<>();
            List<Long> pagePointsNum = new ArrayList<>();
            pagePointsNum.add((i + 1L) * pointStep);
            chunkPagePointsNum.add(pagePointsNum);
            TsFileResource resource = new TsFileResource(new File(SEQ_DIRS, String.format("%d-%d-0-0.tsfile", i + 1, i + 1)));
            sourceFiles.add(resource);
            CompactionFileGeneratorUtils.writeTsFile(fullPathSetWithDeleted, chunkPagePointsNum, i * 1500L, resource);
        }
        Map<PartialPath, List<TimeValuePair>> originData = CompactionCheckerUtils.getDataByQuery(paths, schemaList, sourceFiles, new ArrayList<>());
        TsFileNameGenerator.TsFileName tsFileName = TsFileNameGenerator.getTsFileName(sourceFiles.get(0).getTsFile().getName());
        TsFileResource targetResource = new TsFileResource(new File(SEQ_DIRS, String.format("%d-%d-%d-%d.tsfile", tsFileName.getTime(), tsFileName.getVersion(), tsFileName.getInnerCompactionCnt() + 1, tsFileName.getCrossCompactionCnt())));
        new ReadChunkCompactionPerformer(sourceFiles, targetResource).perform();
        Map<String, List<List<Long>>> chunkPagePointsNumMerged = new HashMap<>();
        // outer list is a chunk, inner list is point num in each page
        List<List<Long>> chunkPointsArray = new ArrayList<>();
        List<Long> pointsArray = new ArrayList<>();
        long curPointNum = 0L;
        for (int i = 0; i < fileNum; ++i) {
            curPointNum += (i + 1L) * pointStep;
            pointsArray.add((i + 1L) * pointStep);
            if (curPointNum > testTargetChunkPointNum) {
                chunkPointsArray.add(pointsArray);
                pointsArray = new ArrayList<>();
                curPointNum = 0;
            }
        }
        if (curPointNum > 0) {
            chunkPointsArray.add(pointsArray);
        }
        for (String path : fullPathSetWithDeleted) {
            chunkPagePointsNumMerged.put(path, chunkPointsArray);
        }
        chunkPagePointsNumMerged.put(deletedPath, null);
        CompactionCheckerUtils.checkChunkAndPage(chunkPagePointsNumMerged, targetResource);
        Map<PartialPath, List<TimeValuePair>> compactedData = CompactionCheckerUtils.getDataByQuery(paths, schemaList, Collections.singletonList(targetResource), new ArrayList<>());
        CompactionCheckerUtils.validDataByValueList(originData, compactedData);
    } finally {
        IoTDBDescriptor.getInstance().getConfig().setTargetChunkSize(originTargetChunkSize);
        IoTDBDescriptor.getInstance().getConfig().setTargetChunkPointNum(originTargetChunkPointNum);
        IoTDBDescriptor.getInstance().getConfig().setChunkSizeLowerBoundInCompaction(originChunkSizeLowerBound);
        IoTDBDescriptor.getInstance().getConfig().setChunkPointNumLowerBoundInCompaction(originChunkPointNumLowerBound);
    }
}

