        TsFileReader readTsFile = new TsFileReader(reader)) {
        QueryExpression queryExpression = QueryExpression.create(Collections.singletonList(path), null);
        QueryDataSet queryDataSet = readTsFile.query(queryExpression);
        int cut = 0;
