    createFiles(3, 3, 4, 200, 20, 10020, 30, 30, true, false);
    createFiles(2, 1, 5, 100, 450, 20450, 0, 0, true, false);
    // generate mods file
    List<String> seriesPaths = new ArrayList<>();
    for (int i = 0; i < 5; i++) {
        seriesPaths.add(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + TsFileGeneratorUtils.getAlignDeviceOffset() + PATH_SEPARATOR + "s" + i);
        seriesPaths.add(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + (TsFileGeneratorUtils.getAlignDeviceOffset() + 1) + PATH_SEPARATOR + "s" + i);
        seriesPaths.add(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + (TsFileGeneratorUtils.getAlignDeviceOffset() + 2) + PATH_SEPARATOR + "s" + i);
    }
    generateModsFile(seriesPaths, seqResources, Long.MIN_VALUE, Long.MAX_VALUE);
    generateModsFile(seriesPaths, unseqResources, Long.MIN_VALUE, Long.MAX_VALUE);
    for (TsFileResource resource : seqResources) {
        resource.setTimeIndexType((byte) 2);
    }
    for (TsFileResource resource : unseqResources) {
        resource.setTimeIndexType((byte) 2);
    }
    for (int i = TsFileGeneratorUtils.getAlignDeviceOffset(); i < TsFileGeneratorUtils.getAlignDeviceOffset() + 4; i++) {
        for (int j = 0; j < 5; j++) {
            List<IMeasurementSchema> schemas = new ArrayList<>();
            schemas.add(new MeasurementSchema("s" + j, TSDataType.INT64));
            AlignedPath path = new AlignedPath(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + i, Collections.singletonList("s" + j), schemas);
            IBatchReader tsFilesReader = new SeriesRawDataBatchReader(path, TSDataType.VECTOR, EnvironmentUtils.TEST_QUERY_CONTEXT, seqResources, unseqResources, null, null, true);
            int count = 0;
            while (tsFilesReader.hasNextBatch()) {
                BatchData batchData = tsFilesReader.nextBatch();
                while (batchData.hasCurrent()) {
                    if (i == TsFileGeneratorUtils.getAlignDeviceOffset() && ((450 <= batchData.currentTime() && batchData.currentTime() < 550) || (550 <= batchData.currentTime() && batchData.currentTime() < 650))) {
                        assertEquals(batchData.currentTime() + 20000, ((TsPrimitiveType[]) (batchData.currentValue()))[0].getValue());
                    } else if ((i < TsFileGeneratorUtils.getAlignDeviceOffset() + 3 && j < 4) && ((20 <= batchData.currentTime() && batchData.currentTime() < 220) || (250 <= batchData.currentTime() && batchData.currentTime() < 450) || (480 <= batchData.currentTime() && batchData.currentTime() < 680))) {
                        assertEquals(batchData.currentTime() + 10000, ((TsPrimitiveType[]) (batchData.currentValue()))[0].getValue());
                    } else {
                        assertEquals(batchData.currentTime(), ((TsPrimitiveType[]) (batchData.currentValue()))[0].getValue());
