            if ((i == TsFileGeneratorUtils.getAlignDeviceOffset()) || (i == TsFileGeneratorUtils.getAlignDeviceOffset() + 1) || (i == TsFileGeneratorUtils.getAlignDeviceOffset() + 2)) {
