        channel.truncate(targetResource.getTsFile().length() - 100);
        channel.close();
        FileUtils.moveDirectory(new File(TestConstant.BASE_OUTPUT_PATH + File.separator + "data"), new File(TestConstant.BASE_OUTPUT_PATH + File.separator + "data1"));
