        CompactionRecoverTask recoverTask = new CompactionRecoverTask(COMPACTION_TEST_SG, "0", tsFileManager, new File(logFilePath), true);
        recoverTask.doCompaction();
        // all the source file should be deleted
        for (String sourceFileName : sourceFileNames) {
            Assert.assertTrue(new File(TestConstant.BASE_OUTPUT_PATH + File.separator + "data1" + File.separator + "sequence" + File.separator + COMPACTION_TEST_SG + File.separator + "0" + File.separator + "0", sourceFileName).exists());
