        Assert.assertFalse(new File(TestConstant.BASE_OUTPUT_PATH + File.separator + "data1" + File.separator + "sequence" + File.separator + COMPACTION_TEST_SG + File.separator + "0" + File.separator + "0", targetResource.getTsFile().getName()).exists());
