@Test
public void testMerge() throws WriteProcessException, QueryProcessException, IllegalPathException, TriggerExecutionException {
    int originCandidateFileNum = IoTDBDescriptor.getInstance().getConfig().getMaxInnerCompactionCandidateFileNum();
    IoTDBDescriptor.getInstance().getConfig().setMaxInnerCompactionCandidateFileNum(9);
    boolean originEnableSeqSpaceCompaction = IoTDBDescriptor.getInstance().getConfig().isEnableSeqSpaceCompaction();
    boolean originEnableUnseqSpaceCompaction = IoTDBDescriptor.getInstance().getConfig().isEnableUnseqSpaceCompaction();
    IoTDBDescriptor.getInstance().getConfig().setEnableSeqSpaceCompaction(true);
    IoTDBDescriptor.getInstance().getConfig().setEnableUnseqSpaceCompaction(true);
    for (int j = 21; j <= 30; j++) {
        TSRecord record = new TSRecord(j, deviceId);
        record.addTuple(DataPoint.getDataPoint(TSDataType.INT32, measurementId, String.valueOf(j)));
        dataRegion.insert(buildInsertRowNodeByTSRecord(record));
        dataRegion.asyncCloseAllWorkingTsFileProcessors();
    }
    dataRegion.syncCloseAllWorkingTsFileProcessors();
    for (int j = 10; j >= 1; j--) {
        TSRecord record = new TSRecord(j, deviceId);
        record.addTuple(DataPoint.getDataPoint(TSDataType.INT32, measurementId, String.valueOf(j)));
        dataRegion.insert(buildInsertRowNodeByTSRecord(record));
        dataRegion.asyncCloseAllWorkingTsFileProcessors();
    }
    dataRegion.syncCloseAllWorkingTsFileProcessors();
    dataRegion.compact();
    long totalWaitingTime = 0;
    while (CompactionTaskManager.getInstance().getExecutingTaskCount() > 0) {
        // wait
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        totalWaitingTime += 100;
        if (totalWaitingTime % 1000 == 0) {
            logger.warn("has waited for {} seconds", totalWaitingTime / 1000);
        }
        if (totalWaitingTime > 120_000) {
            Assert.fail();
            break;
        }
    }
    QueryDataSource queryDataSource = dataRegion.query(Collections.singletonList(new PartialPath(deviceId, measurementId)), deviceId, context, null, null);
    Assert.assertEquals(2, queryDataSource.getSeqResources().size());
    for (TsFileResource resource : queryDataSource.getSeqResources()) {
        Assert.assertTrue(resource.isClosed());
    }
    for (TsFileResource resource : queryDataSource.getUnseqResources()) {
        Assert.assertTrue(resource.isClosed());
    }
    IoTDBDescriptor.getInstance().getConfig().setMaxInnerCompactionCandidateFileNum(originCandidateFileNum);
    IoTDBDescriptor.getInstance().getConfig().setEnableSeqSpaceCompaction(originEnableSeqSpaceCompaction);
    IoTDBDescriptor.getInstance().getConfig().setEnableUnseqSpaceCompaction(originEnableUnseqSpaceCompaction);
}

@Test
public void testDeleteStorageGroupWhenCompacting() throws Exception {
    IoTDBDescriptor.getInstance().getConfig().setMaxInnerCompactionCandidateFileNum(10);
    try {
        for (int j = 0; j < 10; j++) {
            TSRecord record = new TSRecord(j, deviceId);
            record.addTuple(DataPoint.getDataPoint(TSDataType.INT32, measurementId, String.valueOf(j)));
            dataRegion.insert(buildInsertRowNodeByTSRecord(record));
            dataRegion.asyncCloseAllWorkingTsFileProcessors();
        }
        dataRegion.syncCloseAllWorkingTsFileProcessors();
        InnerSpaceCompactionTask task = new InnerSpaceCompactionTask(0, dataRegion.getTsFileManager(), dataRegion.getSequenceFileList(), true, new ReadChunkCompactionPerformer(dataRegion.getSequenceFileList()), new AtomicInteger(0));
        CompactionTaskManager.getInstance().submitTask(task);
        Thread.sleep(20);
        StorageEngine.getInstance().deleteStorageGroup(new PartialPath(storageGroup));
        Thread.sleep(500);
        for (TsFileResource resource : dataRegion.getSequenceFileList()) {
            Assert.assertFalse(resource.getTsFile().exists());
        }
        TsFileResource targetTsFileResource = TsFileNameGenerator.getInnerCompactionTargetFileResource(dataRegion.getSequenceFileList(), true);
        Assert.assertFalse(targetTsFileResource.getTsFile().exists());
        String dataDirectory = targetTsFileResource.getTsFile().getParent();
        File logFile = new File(dataDirectory + File.separator + targetTsFileResource.getTsFile().getName() + CompactionLogger.INNER_COMPACTION_LOG_NAME_SUFFIX);
        Assert.assertFalse(logFile.exists());
        Assert.assertFalse(IoTDBDescriptor.getInstance().getConfig().isReadOnly());
        Assert.assertTrue(dataRegion.getTsFileManager().isAllowCompaction());
    } finally {
        new CompactionConfigRestorer().restoreCompactionConfig();
    }
}

@Test
public void testTimedFlushSeqMemTable() throws IllegalPathException, InterruptedException, WriteProcessException, TriggerExecutionException, ShutdownException {
    // create one sequence memtable
    TSRecord record = new TSRecord(10000, deviceId);
    record.addTuple(DataPoint.getDataPoint(TSDataType.INT32, measurementId, String.valueOf(1000)));
    dataRegion.insert(buildInsertRowNodeByTSRecord(record));
    Assert.assertEquals(1, MemTableManager.getInstance().getCurrentMemtableNumber());
    // change config & reboot timed service
    boolean prevEnableTimedFlushSeqMemtable = config.isEnableTimedFlushSeqMemtable();
    long preFLushInterval = config.getSeqMemtableFlushInterval();
    config.setEnableTimedFlushSeqMemtable(true);
    config.setSeqMemtableFlushInterval(5);
    StorageEngine.getInstance().rebootTimedService();
    Thread.sleep(500);
    Assert.assertEquals(1, dataRegion.getWorkSequenceTsFileProcessors().size());
    TsFileProcessor tsFileProcessor = dataRegion.getWorkSequenceTsFileProcessors().iterator().next();
    FlushManager flushManager = FlushManager.getInstance();
    // flush the sequence memtable
    dataRegion.timedFlushSeqMemTable();
    // wait until memtable flush task is done
    int waitCnt = 0;
    while (tsFileProcessor.getFlushingMemTableSize() != 0 || tsFileProcessor.isManagedByFlushManager() || flushManager.getNumberOfPendingTasks() != 0 || flushManager.getNumberOfPendingSubTasks() != 0 || flushManager.getNumberOfWorkingTasks() != 0 || flushManager.getNumberOfWorkingSubTasks() != 0) {
        Thread.sleep(500);
        ++waitCnt;
        if (waitCnt % 10 == 0) {
            logger.info("already wait {} s", waitCnt / 2);
        }
    }
    Assert.assertEquals(0, MemTableManager.getInstance().getCurrentMemtableNumber());
    config.setEnableTimedFlushSeqMemtable(prevEnableTimedFlushSeqMemtable);
    config.setSeqMemtableFlushInterval(preFLushInterval);
}

