@Test
public void testUnseqUnsealedDelete() throws WriteProcessException, IOException, MetadataException, TriggerExecutionException {
    TSRecord record = new TSRecord(10000, deviceId);
    record.addTuple(DataPoint.getDataPoint(TSDataType.INT32, measurementId, String.valueOf(1000)));
    processor.insert(new InsertRowPlan(record));
    processor.syncCloseAllWorkingTsFileProcessors();
    for (int j = 1; j <= 10; j++) {
        record = new TSRecord(j, deviceId);
        record.addTuple(DataPoint.getDataPoint(TSDataType.INT32, measurementId, String.valueOf(j)));
        processor.insert(new InsertRowPlan(record));
    }
    for (TsFileProcessor tsfileProcessor : processor.getWorkUnsequenceTsFileProcessors()) {
        tsfileProcessor.syncFlush();
    }
    for (int j = 11; j <= 20; j++) {
        record = new TSRecord(j, deviceId);
        record.addTuple(DataPoint.getDataPoint(TSDataType.INT32, measurementId, String.valueOf(j)));
        processor.insert(new InsertRowPlan(record));
    }
    PartialPath fullPath = new MeasurementPath(deviceId, measurementId, new MeasurementSchema(measurementId, TSDataType.INT32, TSEncoding.RLE, CompressionType.UNCOMPRESSED, Collections.emptyMap()));
    processor.delete(new PartialPath(deviceId, measurementId), 0, 15L, -1, null);
    List<TsFileResource> tsfileResourcesForQuery = new ArrayList<>();
    for (TsFileProcessor tsfileProcessor : processor.getWorkUnsequenceTsFileProcessors()) {
        tsfileProcessor.query(Collections.singletonList(fullPath), EnvironmentUtils.TEST_QUERY_CONTEXT, tsfileResourcesForQuery);
    }
    Assert.assertEquals(1, tsfileResourcesForQuery.size());
    List<ReadOnlyMemChunk> memChunks = tsfileResourcesForQuery.get(0).getReadOnlyMemChunk(fullPath);
    long time = 16;
    for (ReadOnlyMemChunk memChunk : memChunks) {
        IPointReader iterator = memChunk.getPointReader();
        while (iterator.hasNextTimeValuePair()) {
