@Test
public void testDeviceIDReusing() throws QueryProcessException, MetadataException, InterruptedException, QueryFilterOptimizationException, StorageEngineException, IOException {
    InsertRowPlan rowPlan = getInsertRowPlan();
    PlanExecutor executor = new PlanExecutor();
    executor.insert(rowPlan);
    QueryPlan queryPlan = (QueryPlan) processor.parseSQLToPhysicalPlan("select * from root.isp.d1");
    QueryDataSet dataSet = executor.processQuery(queryPlan, EnvironmentUtils.TEST_QUERY_CONTEXT);
    Assert.assertEquals(6, dataSet.getPaths().size());
    while (dataSet.hasNext()) {
        RowRecord record = dataSet.next();
        Assert.assertEquals(6, record.getFields().size());
    }
    IDeviceID idTableDeviceID = null;
    for (Map<IDeviceID, DeviceEntry> map : IDTableManager.getInstance().getIDTable(new PartialPath("root.isp.d1")).getIdTables()) {
        if (map == null) {
            continue;
        }
        for (IDeviceID deviceID : map.keySet()) {
            if (idTableDeviceID == null) {
                idTableDeviceID = deviceID;
            } else {
                fail("there should only be one device in id table");
            }
        }
    }
    assertNotNull(idTableDeviceID);
    int deviceCount = 0;
    for (TsFileProcessor processor : StorageEngine.getInstance().getProcessor(new PartialPath("root.isp.d1")).getWorkSequenceTsFileProcessors()) {
        for (Map.Entry<IDeviceID, IWritableMemChunkGroup> entry : processor.getWorkMemTable().getMemTableMap().entrySet()) {
            // using '!=' to check is same device id
            if (entry.getKey() != rowPlan.getDeviceID()) {
                fail("memtable's device id is not same as insert plan's device id");
            }
            // using '!=' to check is same device id
            if (entry.getKey() != idTableDeviceID) {
                fail("memtable's device id is not same as insert plan's device id");
            }
            deviceCount++;
        }
    }
    assertEquals(1, deviceCount);
}

