@Test
public void testSplitPathToNodes() throws IllegalPathException {
    assertArrayEquals(Arrays.asList("root", "sg", "d1", "s1").toArray(), PathUtils.splitPathToDetachedPath("root.sg.d1.s1"));
    assertArrayEquals(Arrays.asList("root", "sg", "d1", "s+1").toArray(), PathUtils.splitPathToDetachedPath("root.sg.d1.`s+1`"));
    assertArrayEquals(Arrays.asList("root", "\"s g\"", "d1", "\"s+1\"").toArray(), PathUtils.splitPathToDetachedPath("root.`\"s g\"`.d1.`\"s+1\"`"));
    assertArrayEquals(Arrays.asList("root", "1").toArray(), PathUtils.splitPathToDetachedPath("root.1"));
    assertArrayEquals(Arrays.asList("root", "sg", "d1", "s", "1").toArray(), PathUtils.splitPathToDetachedPath("root.sg.d1.s.1"));
    assertArrayEquals(Arrays.asList("root", "sg", "d1", "`a.b`").toArray(), PathUtils.splitPathToDetachedPath("root.sg.d1.```a.b```"));
    assertArrayEquals(Arrays.asList("root", "sg", "d1", "`").toArray(), PathUtils.splitPathToDetachedPath("root.sg.d1.````"));
    assertArrayEquals(Arrays.asList("root", "sg", "d1", "`").toArray(), PathUtils.splitPathToDetachedPath("`root`.`sg`.`d1`.````"));
    assertArrayEquals(Arrays.asList("root", "sg", "d1", "`").toArray(), PathUtils.splitPathToDetachedPath("`root`.sg.`d1`.````"));
    assertArrayEquals(Arrays.asList("root", "sg", "d1.`").toArray(), PathUtils.splitPathToDetachedPath("root.sg.`d1.```"));
    assertArrayEquals(Arrays.asList("root", "sg", "\"d").toArray(), PathUtils.splitPathToDetachedPath("root.sg.`\\\"d`"));
    assertArrayEquals(Arrays.asList("root", "sg", "\td").toArray(), PathUtils.splitPathToDetachedPath("root.sg.`\\td`"));
    assertArrayEquals(Arrays.asList("root", "sg", "\\td").toArray(), PathUtils.splitPathToDetachedPath("root.sg.`\\\\td`"));
    assertArrayEquals(Arrays.asList("root", "laptop", "d1", "\"1.2.3\"").toArray(), PathUtils.splitPathToDetachedPath("root.laptop.d1.`\\\"1.2.3\\\"`"));
    try {
        PathUtils.splitPathToDetachedPath("root.sg.d1.```");
        fail();
    } catch (IllegalPathException e) {
        Assert.assertEquals("root.sg.d1.``` is not a legal path", e.getMessage());
    }
    try {
        PathUtils.splitPathToDetachedPath("root.sg.`d1`..`aa``b`");
        fail();
    } catch (IllegalPathException e) {
        Assert.assertEquals("root.sg.`d1`..`aa``b` is not a legal path", e.getMessage());
    }
    try {
        PathUtils.splitPathToDetachedPath("root.sg.d1.`s+`-1\"`");
        fail();
    } catch (IllegalPathException e) {
        Assert.assertEquals("root.sg.d1.`s+`-1\"` is not a legal path", e.getMessage());
    }
    try {
        PathUtils.splitPathToDetachedPath("root..a");
        fail();
    } catch (IllegalPathException e) {
        Assert.assertEquals("root..a is not a legal path", e.getMessage());
    }
    try {
        PathUtils.splitPathToDetachedPath("root.sg.d1.");
        fail();
    } catch (IllegalPathException e) {
        Assert.assertEquals("root.sg.d1. is not a legal path", e.getMessage());
    }
}

