        assertFalse(storageGroup.isPathExist(new PartialPath("root.laptop.d1.s1")));
    } catch (MetadataException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        root.setStorageGroup(new PartialPath("root.laptop"));
    } catch (MetadataException e) {
        Assert.assertEquals("some children of root.laptop have already been set to storage group", e.getMessage());
    }
    // check timeseries
    assertFalse(storageGroup.isPathExist(new PartialPath("root.laptop.d1.s0")));
    assertFalse(storageGroup.isPathExist(new PartialPath("root.laptop.d1.s1")));
    try {
        assertEquals("root.laptop.d1", root.getBelongedStorageGroup(new PartialPath("root.laptop.d1.s0")).getFullPath());
        storageGroup.createTimeseries(new PartialPath("root.laptop.d1.s0"), TSDataType.INT32, TSEncoding.RLE, TSFileDescriptor.getInstance().getConfig().getCompressor(), Collections.emptyMap(), null);
        assertEquals("root.laptop.d1", root.getBelongedStorageGroup(new PartialPath("root.laptop.d1.s1")).getFullPath());
        storageGroup.createTimeseries(new PartialPath("root.laptop.d1.s1"), TSDataType.INT32, TSEncoding.RLE, TSFileDescriptor.getInstance().getConfig().getCompressor(), Collections.emptyMap(), null);
    } catch (MetadataException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        storageGroup.deleteTimeseriesAndReturnEmptyStorageGroup(new PartialPath("root.laptop.d1.s0"));
    } catch (MetadataException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    assertFalse(storageGroup.isPathExist(new PartialPath("root.laptop.d1.s0")));
    try {
        root.deleteStorageGroup(new PartialPath("root.laptop.d1"));
    } catch (MetadataException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    assertFalse(root.isStorageGroupAlreadySet(new PartialPath("root.laptop.d1.s1")));
    assertFalse(root.isStorageGroupAlreadySet(new PartialPath("root.laptop.d1")));
    assertFalse(root.isStorageGroupAlreadySet(new PartialPath("root.laptop")));
}

