@Test
public void testRecover() throws Exception {
    LocalSchemaProcessor schemaProcessor = IoTDB.schemaProcessor;
    try {
        schemaProcessor.setStorageGroup(new PartialPath("root.laptop.d1"));
        schemaProcessor.setStorageGroup(new PartialPath("root.laptop.d2"));
        schemaProcessor.createTimeseries(new PartialPath("root.laptop.d1.s1"), TSDataType.INT32, TSEncoding.PLAIN, CompressionType.GZIP, null);
        schemaProcessor.createTimeseries(new PartialPath("root.laptop.d2.s1"), TSDataType.INT32, TSEncoding.PLAIN, CompressionType.GZIP, null);
        assertTrue(schemaProcessor.isStorageGroup(new PartialPath("root.laptop.d1")));
        assertTrue(schemaProcessor.isStorageGroup(new PartialPath("root.laptop.d2")));
        assertFalse(schemaProcessor.isStorageGroup(new PartialPath("root.laptop.d3")));
        assertFalse(schemaProcessor.isStorageGroup(new PartialPath("root.laptop")));
        Set<String> devices = new TreeSet<String>() {

            {
                add("root.laptop.d1");
                add("root.laptop.d2");
            }
        };
        // prefix with *
        assertEquals(devices, schemaProcessor.getMatchedDevices(new PartialPath("root.**"), false).stream().map(PartialPath::getFullPath).collect(Collectors.toSet()));
        schemaProcessor.deleteStorageGroups(Collections.singletonList(new PartialPath("root.laptop.d2")));
        assertTrue(schemaProcessor.isStorageGroup(new PartialPath("root.laptop.d1")));
        assertFalse(schemaProcessor.isStorageGroup(new PartialPath("root.laptop.d2")));
        assertFalse(schemaProcessor.isStorageGroup(new PartialPath("root.laptop.d3")));
        assertFalse(schemaProcessor.isStorageGroup(new PartialPath("root.laptop")));
        devices.remove("root.laptop.d2");
        // prefix with *
        assertEquals(devices, schemaProcessor.getMatchedDevices(new PartialPath("root.**"), false).stream().map(PartialPath::getFullPath).collect(Collectors.toSet()));
        EnvironmentUtils.restartDaemon();
        assertTrue(schemaProcessor.isStorageGroup(new PartialPath("root.laptop.d1")));
        assertFalse(schemaProcessor.isStorageGroup(new PartialPath("root.laptop.d2")));
        assertFalse(schemaProcessor.isStorageGroup(new PartialPath("root.laptop.d3")));
        assertFalse(schemaProcessor.isStorageGroup(new PartialPath("root.laptop")));
        // prefix with *
        assertEquals(devices, schemaProcessor.getMatchedDevices(new PartialPath("root.**"), false).stream().map(PartialPath::getFullPath).collect(Collectors.toSet()));
    } catch (MetadataException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

