    for (int i = 0; i < 3; i++) {
        SetTemplatePlan setTemplatePlan = new SetTemplatePlan("template1", String.format("root.sg%d.d%d", i, i + 1));
        schemaProcessor.setSchemaTemplate(setTemplatePlan);
    }
    assertEquals(new HashSet<>(Arrays.asList("root.sg1.d2", "root.sg0.d1", "root.sg2.d3")), schemaProcessor.getPathsSetTemplate("*"));
    assertEquals(new HashSet<>(Arrays.asList()), schemaProcessor.getPathsSetTemplate("treeTemplate"));
    for (int i = 0; i < 3; i++) {
        SetTemplatePlan setTemplatePlan = new SetTemplatePlan("treeTemplate", String.format("root.tsg%d.d%d", i + 9, i + 10));
        schemaProcessor.setSchemaTemplate(setTemplatePlan);
    }
    assertEquals(new HashSet<>(Arrays.asList("root.tsg10.d11", "root.tsg11.d12", "root.tsg9.d10")), schemaProcessor.getPathsSetTemplate("treeTemplate"));
    assertEquals(new HashSet<>(Arrays.asList("root.tsg10.d11", "root.tsg11.d12", "root.tsg9.d10", "root.sg1.d2", "root.sg0.d1", "root.sg2.d3")), schemaProcessor.getPathsSetTemplate("*"));
    PlanExecutor exe1 = new PlanExecutor();
    exe1.insert(getInsertRowPlan("root.sg0.d1", "s11"));
    exe1.insert(getInsertRowPlan("root.sg1.d2", "s11"));
    exe1.insert(getInsertRowPlan("root.tsg10.d11.d1", "s1"));
    assertEquals(new HashSet<>(Arrays.asList("root.tsg10.d11", "root.sg1.d2", "root.sg0.d1")), schemaProcessor.getPathsUsingTemplate("*"));
    try {
        schemaProcessor.createSchemaTemplate(plan1);
        fail();
    } catch (MetadataException e) {
        assertEquals("Duplicated template name: treeTemplate", e.getMessage());
    }
    try {
        schemaProcessor.dropSchemaTemplate(new DropTemplatePlan("treeTemplate"));
        fail();
    } catch (MetadataException e) {
        assertEquals("Template [treeTemplate] has been set on MTree, cannot be dropped now.", e.getMessage());
    }
}

