    Assert.assertTrue(sinkHandle.isFull().isDone());
    Assert.assertFalse(sinkHandle.isFinished());
    Assert.assertFalse(sinkHandle.isAborted());
    Assert.assertEquals(mockTsBlockSize * numOfMockTsBlock, sinkHandle.getBufferRetainedSizeInBytes());
    Assert.assertEquals(numOfMockTsBlock, sinkHandle.getNumOfBufferedTsBlocks());
    Mockito.verify(mockMemoryPool, Mockito.times(1)).reserve(queryId, mockTsBlockSize * numOfMockTsBlock);
    try {
        Thread.sleep(100L);
        Mockito.verify(mockClient, Mockito.times(1)).onNewDataBlockEvent(Mockito.argThat(e -> remoteFragmentInstanceId.equals(e.getTargetFragmentInstanceId()) && remotePlanNodeId.equals(e.getTargetPlanNodeId()) && localFragmentInstanceId.equals(e.getSourceFragmentInstanceId()) && e.getStartSequenceId() == 0 && e.getBlockSizes().size() == numOfMockTsBlock));
    } catch (InterruptedException | TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    // Get tsblocks.
    for (int i = 0; i < numOfMockTsBlock; i++) {
        try {
            sinkHandle.getSerializedTsBlock(i);
        } catch (IOException e) {
            e.printStackTrace();
            Assert.fail();
        }
        Assert.assertTrue(sinkHandle.isFull().isDone());
    }
    Assert.assertFalse(sinkHandle.isFinished());
    // Set no-more-tsblocks.
    sinkHandle.setNoMoreTsBlocks();
    Assert.assertTrue(sinkHandle.isFull().isDone());
    Assert.assertFalse(sinkHandle.isFinished());
    Assert.assertFalse(sinkHandle.isAborted());
    Mockito.verify(mockSinkHandleListener, Mockito.times(1)).onEndOfBlocks(sinkHandle);
    // Ack tsblocks.
    sinkHandle.acknowledgeTsBlock(0, numOfMockTsBlock);
    Assert.assertTrue(sinkHandle.isFull().isDone());
    Assert.assertTrue(sinkHandle.isFinished());
    Assert.assertFalse(sinkHandle.isAborted());
    Assert.assertEquals(0L, sinkHandle.getBufferRetainedSizeInBytes());
    Mockito.verify(mockMemoryPool, Mockito.times(1)).free(queryId, numOfMockTsBlock * mockTsBlockSize);
    Mockito.verify(mockSinkHandleListener, Mockito.times(1)).onFinish(sinkHandle);
    try {
