        }).when(mockClient).getDataBlock(Mockito.any(TGetDataBlockRequest.class));
    } catch (TException | IOException e) {
        e.printStackTrace();
        Assert.fail();
    }
    SourceHandle sourceHandle = new SourceHandle(remoteEndpoint, remoteFragmentInstanceId, localFragmentInstanceId, localPlanNodeId, mockLocalMemoryManager, Executors.newSingleThreadExecutor(), mockTsBlockSerde, mockSourceHandleListener, mockClientManager);
    Assert.assertFalse(sourceHandle.isBlocked().isDone());
    Assert.assertFalse(sourceHandle.isAborted());
    Assert.assertFalse(sourceHandle.isFinished());
    Assert.assertEquals(0L, sourceHandle.getBufferRetainedSizeInBytes());
    // New data blocks event arrived in unordered manner.
    sourceHandle.updatePendingDataBlockInfo(numOfMockTsBlock, Stream.generate(() -> mockTsBlockSize).limit(numOfMockTsBlock).collect(Collectors.toList()));
    try {
        Thread.sleep(100L);
        Mockito.verify(mockClient, Mockito.times(0)).getDataBlock(Mockito.any(TGetDataBlockRequest.class));
        Mockito.verify(mockClient, Mockito.times(0)).onAcknowledgeDataBlockEvent(Mockito.any(TAcknowledgeDataBlockEvent.class));
    } catch (InterruptedException | TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertFalse(sourceHandle.isBlocked().isDone());
    Assert.assertFalse(sourceHandle.isAborted());
    Assert.assertFalse(sourceHandle.isFinished());
    Assert.assertEquals(0L, sourceHandle.getBufferRetainedSizeInBytes());
    sourceHandle.updatePendingDataBlockInfo(0, Stream.generate(() -> mockTsBlockSize).limit(numOfMockTsBlock).collect(Collectors.toList()));
    try {
        Thread.sleep(100L);
        Mockito.verify(mockClient, Mockito.times(1)).getDataBlock(Mockito.argThat(req -> remoteFragmentInstanceId.equals(req.getSourceFragmentInstanceId()) && 0 == req.getStartSequenceId() && numOfMockTsBlock * 2 == req.getEndSequenceId()));
        Mockito.verify(mockClient, Mockito.times(1)).onAcknowledgeDataBlockEvent(Mockito.argThat(e -> remoteFragmentInstanceId.equals(e.getSourceFragmentInstanceId()) && 0 == e.getStartSequenceId() && numOfMockTsBlock * 2 == e.getEndSequenceId()));
    } catch (InterruptedException | TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertTrue(sourceHandle.isBlocked().isDone());
    Assert.assertFalse(sourceHandle.isAborted());
    Assert.assertFalse(sourceHandle.isFinished());
    Assert.assertEquals(numOfMockTsBlock * 2 * mockTsBlockSize, sourceHandle.getBufferRetainedSizeInBytes());
    // The local fragment instance consumes the data blocks.
    for (int i = 0; i < 2 * numOfMockTsBlock; i++) {
        sourceHandle.receive();
        if (i < 2 * numOfMockTsBlock - 1) {
            Assert.assertTrue(sourceHandle.isBlocked().isDone());
        } else {
            Assert.assertFalse(sourceHandle.isBlocked().isDone());
        }
        Assert.assertFalse(sourceHandle.isAborted());
        Assert.assertFalse(sourceHandle.isFinished());
        Assert.assertEquals((2 * numOfMockTsBlock - 1 - i) * mockTsBlockSize, sourceHandle.getBufferRetainedSizeInBytes());
    }
    // New data blocks event arrived.
    sourceHandle.updatePendingDataBlockInfo(numOfMockTsBlock * 2, Stream.generate(() -> mockTsBlockSize).limit(numOfMockTsBlock).collect(Collectors.toList()));
    try {
        Thread.sleep(100L);
        Mockito.verify(mockClient, Mockito.times(1)).getDataBlock(Mockito.argThat(req -> remoteFragmentInstanceId.equals(req.getSourceFragmentInstanceId()) && numOfMockTsBlock * 2 == req.getStartSequenceId() && numOfMockTsBlock * 3 == req.getEndSequenceId()));
        Mockito.verify(mockClient, Mockito.times(1)).onAcknowledgeDataBlockEvent(Mockito.argThat(e -> remoteFragmentInstanceId.equals(e.getSourceFragmentInstanceId()) && numOfMockTsBlock * 2 == e.getStartSequenceId() && numOfMockTsBlock * 3 == e.getEndSequenceId()));
    } catch (InterruptedException | TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertTrue(sourceHandle.isBlocked().isDone());
    Assert.assertFalse(sourceHandle.isAborted());
    Assert.assertFalse(sourceHandle.isFinished());
    Assert.assertEquals(numOfMockTsBlock * mockTsBlockSize, sourceHandle.getBufferRetainedSizeInBytes());
    // The local fragment instance consumes the data blocks.
    for (int i = 0; i < numOfMockTsBlock; i++) {
        sourceHandle.receive();
        if (i < numOfMockTsBlock - 1) {
            Assert.assertTrue(sourceHandle.isBlocked().isDone());
        } else {
            Assert.assertFalse(sourceHandle.isBlocked().isDone());
        }
        Assert.assertFalse(sourceHandle.isAborted());
        Assert.assertFalse(sourceHandle.isFinished());
        Assert.assertEquals((numOfMockTsBlock - 1 - i) * mockTsBlockSize, sourceHandle.getBufferRetainedSizeInBytes());
    }
    // Receive EndOfDataBlock event from upstream fragment instance.
    sourceHandle.setNoMoreTsBlocks(3 * numOfMockTsBlock - 1);
    Assert.assertTrue(sourceHandle.isBlocked().isDone());
    Assert.assertFalse(sourceHandle.isAborted());
    Assert.assertTrue(sourceHandle.isFinished());
    Assert.assertEquals(0L, sourceHandle.getBufferRetainedSizeInBytes());
    Mockito.verify(mockSourceHandleListener, Mockito.times(1)).onFinished(sourceHandle);
}

