    DeviceSchemaInfo deviceSchemaInfo = schemaTree.searchDeviceSchemaInfo(new PartialPath("root.sg.d2.a"), Arrays.asList("s1", "status"));
    Assert.assertTrue(deviceSchemaInfo.isAligned());
