                Assert.assertEquals(0, tsBlock.getTimeByIndex(i));
                for (int j = 0; j < columns.size(); j++) {
                    Binary binary = tsBlock.getColumn(j).isNull(i) ? null : tsBlock.getColumn(j).getBinary(i);
