@Test
public void testInsertNullableTabletPlan() throws QueryProcessException, MetadataException, InterruptedException, QueryFilterOptimizationException, StorageEngineException, IOException {
    long[] times = new long[] { 110L, 111L, 112L, 113L };
    List<Integer> dataTypes = new ArrayList<>();
    dataTypes.add(TSDataType.DOUBLE.ordinal());
    dataTypes.add(TSDataType.FLOAT.ordinal());
    dataTypes.add(TSDataType.INT64.ordinal());
    dataTypes.add(TSDataType.INT32.ordinal());
    dataTypes.add(TSDataType.BOOLEAN.ordinal());
    dataTypes.add(TSDataType.TEXT.ordinal());
    Object[] columns = new Object[6];
    columns[0] = new double[4];
    columns[1] = new float[4];
    columns[2] = new long[4];
    columns[3] = new int[4];
    columns[4] = new boolean[4];
    columns[5] = new Binary[4];
    for (int r = 0; r < 4; r++) {
        ((double[]) columns[0])[r] = 1.0 + r;
        ((float[]) columns[1])[r] = 2 + r;
        ((long[]) columns[2])[r] = 10000 + r;
        ((int[]) columns[3])[r] = 100 + r;
        ((boolean[]) columns[4])[r] = (r % 2 == 0);
        ((Binary[]) columns[5])[r] = new Binary("hh" + r);
    }
    BitMap[] bitMaps = new BitMap[dataTypes.size()];
    for (int i = 0; i < dataTypes.size(); i++) {
        if (bitMaps[i] == null) {
            bitMaps[i] = new BitMap(times.length);
        }
        bitMaps[i].mark(i % times.length);
    }
    InsertTabletPlan tabletPlan = new InsertTabletPlan(new PartialPath("root.isp.d1"), new String[] { "s1", "s2", "s3", "s4", "s5", "s6" }, dataTypes);
    tabletPlan.setTimes(times);
    tabletPlan.setColumns(columns);
    tabletPlan.setRowCount(times.length);
    tabletPlan.setBitMaps(bitMaps);
    PlanExecutor executor = new PlanExecutor();
    executor.insertTablet(tabletPlan);
    QueryPlan queryPlan = (QueryPlan) processor.parseSQLToPhysicalPlan("select * from root.isp.d1");
    QueryDataSet dataSet = executor.processQuery(queryPlan, EnvironmentUtils.TEST_QUERY_CONTEXT);
    Assert.assertEquals(6, dataSet.getPaths().size());
    int rowNum = 0;
    while (dataSet.hasNext()) {
        RowRecord record = dataSet.next();
        Assert.assertEquals(6, record.getFields().size());
        List<Field> fields = record.getFields();
        for (int i = 0; i < 6; ++i) {
            if (i % times.length == rowNum) {
                Assert.assertNull(fields.get(i));
            } else {
                Assert.assertNotNull(fields.get(i));
            }
        }
        rowNum++;
    }
}

