    for (int i = 1000; i >= 0; i--) {
        timeList.add((long) i);
        for (int j = 0; j < 5; j++) {
            vectorArray[j][i] = (long) i;
            if (i % 100 == 0) {
                bitMaps[j].mark(i);
            }
            columnOrder[j] = j;
        }
    }
    tvList.putAlignedValues(ArrayUtils.toPrimitive(timeList.toArray(new Long[0])), vectorArray, bitMaps, columnOrder, 0, 1000);
    AlignedTVList clonedTvList = tvList.clone();
    for (long i = 0; i < tvList.rowCount; i++) {
        Assert.assertEquals(tvList.getTime((int) i), clonedTvList.getTime((int) i));
        Assert.assertEquals(tvList.getAlignedValue((int) i).toString(), clonedTvList.getAlignedValue((int) i).toString());
        for (int column = 0; i < 5; i++) {
            Assert.assertEquals(tvList.isValueMarked((int) i, column), clonedTvList.isValueMarked((int) i, column));
        }
    }
}

