    float[] data = new float[] { 0.0f, (float) Math.PI, (float) (10 * Math.PI), Integer.MAX_VALUE, -Integer.MAX_VALUE };
    float[][] expData = new float[][] { { 0.0f, 3.0f, 31f, Integer.MAX_VALUE, -Integer.MAX_VALUE }, { 0.0f, 3.1416f, 31.4159f, Integer.MAX_VALUE, -Integer.MAX_VALUE }, { 0.0f, (float) Math.PI, (float) (10 * Math.PI), Integer.MAX_VALUE, -Integer.MAX_VALUE } };
    for (int j = 0; j < size.length; j++) {
        for (int i = 0; i < data.length; i++) {
            float res = MathUtils.roundWithGivenPrecision(data[i], size[j]);
            assertEquals(expData[j][i], res, Float.MIN_NORMAL);
        }
    }
}

