@Test
public void testCreateFunctionPlan() {
    try {
        PhysicalPlan plan = processor.parseSQLToPhysicalPlan("create function udf as 'org.apache.iotdb.db.query.udf.example.Adder'");
        if (plan.isQuery() || !(plan instanceof CreateFunctionPlan)) {
            Assert.fail();
        }
        CreateFunctionPlan createFunctionPlan = (CreateFunctionPlan) plan;
        Assert.assertEquals("udf", createFunctionPlan.getUdfName());
        Assert.assertEquals("org.apache.iotdb.db.query.udf.example.Adder", createFunctionPlan.getClassName());
    } catch (QueryProcessException e) {
        Assert.fail(e.toString());
    }
}

