    boolean[] doubleIsNull = { true, false, false, true, false };
    Binary[] binaryValueArray = { new Binary("19970909"), new Binary("ty"), new Binary("love"), new Binary("zm"), new Binary("19950421") };
    boolean[] binaryIsNull = { false, false, false, false, false };
    TsBlockBuilder builder = new TsBlockBuilder(Arrays.asList(TSDataType.BOOLEAN, TSDataType.INT32, TSDataType.INT64, TSDataType.FLOAT, TSDataType.DOUBLE, TSDataType.TEXT));
    for (int i = 0; i < timeArray.length; i++) {
        builder.getTimeColumnBuilder().writeLong(timeArray[i]);
        if (booleanIsNull[i]) {
            builder.getColumnBuilder(0).appendNull();
        } else {
            builder.getColumnBuilder(0).writeBoolean(booleanValueArray[i]);
        }
        if (intIsNull[i]) {
            builder.getColumnBuilder(1).appendNull();
        } else {
            builder.getColumnBuilder(1).writeInt(intValueArray[i]);
        }
        if (longIsNull[i]) {
            builder.getColumnBuilder(2).appendNull();
        } else {
            builder.getColumnBuilder(2).writeLong(longValueArray[i]);
        }
        if (floatIsNull[i]) {
            builder.getColumnBuilder(3).appendNull();
