        unCompressor.uncompress(compress, 0, 20, uncompress, 0);
        ByteBuffer uncompressedBuffer = ByteBuffer.wrap(uncompress);
        assertEquals(1L, ReadWriteIOUtils.readLong(uncompressedBuffer));
